face.layout_source:
// granulator2.face: the panel for tap/examples/granulators/granulator2.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/granulators/granulator2.face --meta <graph>.cragmeta

face "Granulator 2" {
  row(gap = 10) {
    box "Cloud" { knob.big "Grains" (grains) }
    box "Window" { knob "Position" (window_pos) knob "Size" (window_size) }
    box "Speed" { knob "Min" (speed_min) knob "Max" (speed_max) }
    box "Length" { knob "Min" (grain_min) knob "Max" (grain_max) }
    box "Skew" { knob "Min" (skew_min) knob "Max" (skew_max) }
    box "Output" { knob "Gain" (output_gain) }
  }
  viz(h = 90)
}
